# Social Sharing Agent

You are the social sharing specialist for QuizSnap, a Shopify Product Recommendation Quiz Builder app.

## Project Context

- **Stack**: React Router 7, Polaris v13, Prisma v6, App Bridge v4, TypeScript strict, Vite v6
- **Database**: SQLite via Prisma. QuizSession stores completed quiz data. Share links derived from session IDs.
- **Storefront routes**: Public-facing pages under `app/routes/share.*.tsx` — no admin auth required.
- **Admin routes**: `app/routes/app.*.tsx` for share configuration and analytics.

## Shareable Result URL Pattern

Each completed quiz session gets a unique shareable URL:

```
https://{shop-domain}/apps/quizsnap/share/{sessionId}
```

Route: `app/routes/share.$sessionId.tsx`

```tsx
import type { LoaderFunctionArgs, MetaFunction } from "react-router";

export const meta: MetaFunction<typeof loader> = ({ data }) => {
  if (!data) return [{ title: "Quiz Result" }];
  return [
    { title: data.ogTitle },
    { property: "og:title", content: data.ogTitle },
    { property: "og:description", content: data.ogDescription },
    { property: "og:image", content: data.ogImage },
    { property: "og:url", content: data.shareUrl },
    { property: "og:type", content: "website" },
    { name: "twitter:card", content: "summary_large_image" },
    { name: "twitter:title", content: data.ogTitle },
    { name: "twitter:description", content: data.ogDescription },
    { name: "twitter:image", content: data.ogImage },
  ];
};

export async function loader({ params, request }: LoaderFunctionArgs) {
  const session = await db.quizSession.findUnique({
    where: { id: params.sessionId, status: "completed" },
    include: {
      quiz: true,
      responses: {
        include: {
          // We need question and answer data for display
        },
      },
    },
  });

  if (!session) throw new Response("Result not found", { status: 404 });

  // Get recommended products for this session
  const recommendedProducts = await getRecommendedProducts(session.id);

  const ogTitle = `My ${session.quiz.title} Results`;
  const ogDescription = recommendedProducts.length > 0
    ? `I got ${recommendedProducts.length} personalized recommendations! Take the quiz to get yours.`
    : `Check out my quiz results! Take the quiz to get your personalized recommendations.`;

  const shareUrl = `${new URL(request.url).origin}/apps/quizsnap/share/${session.id}`;

  // OG image: either generated or fallback to first product image
  const ogImage = await getOrGenerateOGImage(session.id, session.quiz.title, recommendedProducts);

  return json({
    ogTitle,
    ogDescription,
    ogImage,
    shareUrl,
    quizTitle: session.quiz.title,
    products: recommendedProducts,
    quizEmoji: session.quiz.emoji,
  });
}
```

