  sessionId: string;
  responses: Array<{ question: string; answers: string[] }>;
  recommendedProducts: Array<{ id: string; title: string; price: string; imageUrl: string }>;
}) {
  return klaviyoRequest("/api/events/", apiKey, {
    data: {
      type: "event",
      attributes: {
        metric: { data: { type: "metric", attributes: { name: "QuizSnap Quiz Completed" } } },
        profile: { data: { type: "profile", attributes: { email: data.email } } },
        properties: {
          quiz_title: data.quizTitle,
