```tsx
// Route: app/routes/webhooks.customers-redact.tsx
async function handleCustomerRedact(shopDomain: string, payload: any) {
  const email = payload.customer?.email;
  if (!email) return;

  // Anonymize — remove PII but keep anonymized analytics data
  await db.quizSession.updateMany({
    where: {
      shopperEmail: email,
      quiz: { shop: { shopDomain } },
    },
    data: { shopperEmail: null },
  });

  // Delete any text responses that might contain PII
  const sessions = await db.quizSession.findMany({
    where: { quiz: { shop: { shopDomain } } },
    select: { id: true },
  });
  const sessionIds = sessions.map((s) => s.id);

  await db.quizResponse.updateMany({
    where: { sessionId: { in: sessionIds }, textValue: { not: null } },
    data: { textValue: null },
  });

  console.log(`[GDPR] Customer redacted: ${email} at ${shopDomain}`);
}
