## Export Features

### 1. Export Quiz Responses to CSV

Route: `app/routes/app.quiz.$id.export-responses.tsx`

```tsx
export async function loader({ request, params }: LoaderFunctionArgs) {
  const { session } = await shopify.authenticate.admin(request);
  const shop = await db.shop.findUnique({ where: { shopDomain: session.shop } });

  // Plan gate: Pro+ only
  if (shop?.plan === "free" || shop?.plan === "starter") {
    throw new Response("Export requires Pro plan", { status: 403 });
  }

  const quiz = await db.quiz.findFirst({
    where: { id: params.id, shopId: shop!.id },
    include: {
      questions: { orderBy: { order: "asc" }, include: { answers: true } },
      sessions: {
        where: { status: "completed" },
        include: { responses: true },
        orderBy: { completedAt: "desc" },
      },
    },
  });

  if (!quiz) throw new Response("Quiz not found", { status: 404 });

  // Build CSV
  const headers = [
    "Session ID",
    "Email",
    "Completed At",
    "Purchase Amount",
    "Order ID",
    ...quiz.questions.map((q) => q.title),
  ];

  const rows = quiz.sessions.map((s) => {
    const responseMap = new Map(s.responses.map((r) => [r.questionId, r]));
    return [
      s.id,
      s.shopperEmail ?? "",
      s.completedAt?.toISOString() ?? "",
      s.purchaseAmount?.toString() ?? "",
      s.shopifyOrderId ?? "",
      ...quiz.questions.map((q) => {
        const resp = responseMap.get(q.id);
        if (!resp) return "";
        if (resp.sliderValue !== null) return resp.sliderValue.toString();
        if (resp.textValue) return resp.textValue;
        const answerIds = resp.answerIds.split(",").filter(Boolean);
        const labels = answerIds.map((aid) => {
          const answer = q.answers.find((a) => a.id === aid);
          return answer?.label ?? aid;
        });
        return labels.join("; ");
      }),
    ];
  });

  const csvContent = [headers, ...rows]
    .map((row) => row.map((cell) => `"${String(cell).replace(/"/g, '""')}"`).join(","))
    .join("\n");

  return new Response(csvContent, {
    headers: {
      "Content-Type": "text/csv; charset=utf-8",
      "Content-Disposition": `attachment; filename="quizsnap-${quiz.title.replace(/[^a-z0-9]/gi, "-")}-responses-${Date.now()}.csv"`,
    },
  });
}
```

