- **Admin routes**: `app/routes/app.*.tsx` for share configuration and analytics.

## Shareable Result URL Pattern

Each completed quiz session gets a unique shareable URL:

```
https://{shop-domain}/apps/quizsnap/share/{sessionId}
```

Route: `app/routes/share.$sessionId.tsx`

```tsx
import type { LoaderFunctionArgs, MetaFunction } from "react-router";

export const meta: MetaFunction<typeof loader> = ({ data }) => {
  if (!data) return [{ title: "Quiz Result" }];
  return [
    { title: data.ogTitle },
    { property: "og:title", content: data.ogTitle },
    { property: "og:description", content: data.ogDescription },
    { property: "og:image", content: data.ogImage },
    { property: "og:url", content: data.shareUrl },
    { property: "og:type", content: "website" },
    { name: "twitter:card", content: "summary_large_image" },
    { name: "twitter:title", content: data.ogTitle },
    { name: "twitter:description", content: data.ogDescription },
    { name: "twitter:image", content: data.ogImage },
  ];
};

export async function loader({ params, request }: LoaderFunctionArgs) {
  const session = await db.quizSession.findUnique({
    where: { id: params.sessionId, status: "completed" },
    include: {
      quiz: true,
      responses: true,
    },
  });

  if (!session) throw new Response("Result not found", { status: 404 });

  // Get recommended products for this session
  const recommendedProducts = await getRecommendedProducts(session.id);

  const ogTitle = `My ${session.quiz.title} Results`;
  const ogDescription = recommendedProducts.length > 0
    ? `I got ${recommendedProducts.length} personalized recommendations! Take the quiz to get yours.`
    : `Check out my quiz results! Take the quiz to get your personalized recommendations.`;

  const shareUrl = `${new URL(request.url).origin}/apps/quizsnap/share/${session.id}`;

  // OG image: either generated or fallback to first product image
  const ogImage = recommendedProducts.length > 0 && recommendedProducts[0].imageUrl
    ? recommendedProducts[0].imageUrl
    : "https://cdn.shopify.com/quizsnap/default-share-image.png";

  return json({
    ogTitle,
    ogDescription,
    ogImage,
    shareUrl,
    quizTitle: session.quiz.title,
    products: recommendedProducts,
    quizEmoji: session.quiz.emoji,
  });
}
```

## Share URL Generation

When a quiz is completed, generate the share data and return it to the storefront:

```tsx
function generateShareData(sessionId: string, shopDomain: string, quizTitle: string, products: Product[]) {
  const shareUrl = `https://${shopDomain}/apps/quizsnap/share/${sessionId}`;

  const shareMessages = {
    facebook: shareUrl, // Facebook uses OG tags from the URL
    twitter: `${quizTitle} - Check out my personalized recommendations! ${shareUrl}`,
    pinterest: shareUrl, // Pinterest uses OG tags
    whatsapp: `Hey! I just took the "${quizTitle}" quiz and got amazing recommendations. Take it yourself: ${shareUrl}`,
    email: {
      subject: `My ${quizTitle} Results`,
      body: `I just completed the "${quizTitle}" quiz and got ${products.length} personalized recommendations.\n\nTake the quiz yourself: ${shareUrl}`,
    },
  };

  return { shareUrl, shareMessages };
}
```

## Social Share Buttons Component

```tsx
// Storefront component — rendered on the result page
interface ShareButtonsProps {
  shareUrl: string;
  quizTitle: string;
  productCount: number;
}

function ShareButtons({ shareUrl, quizTitle, productCount }: ShareButtonsProps) {
  const encodedUrl = encodeURIComponent(shareUrl);
  const encodedText = encodeURIComponent(
    `Check out my ${quizTitle} results - ${productCount} personalized picks!`
  );

  const platforms = [
    {
      name: "Facebook",
      url: `https://www.facebook.com/sharer/sharer.php?u=${encodedUrl}`,
      icon: "facebook",
    },
    {
      name: "X (Twitter)",
      url: `https://twitter.com/intent/tweet?url=${encodedUrl}&text=${encodedText}`,
      icon: "twitter",
    },
    {
      name: "Pinterest",
      url: `https://pinterest.com/pin/create/button/?url=${encodedUrl}&description=${encodedText}`,
      icon: "pinterest",
    },
    {
      name: "WhatsApp",
      url: `https://wa.me/?text=${encodedText}%20${encodedUrl}`,
      icon: "whatsapp",
    },
  ];

  const handleShare = (platform: string, url: string) => {
    trackShareEvent(platform);
    window.open(url, "_blank", "width=600,height=400");
  };

  return (
    <div className="quizsnap-share-buttons">
      {platforms.map((p) => (
        <button
          key={p.name}
          onClick={() => handleShare(p.name, p.url)}
          aria-label={`Share on ${p.name}`}
          className={`quizsnap-share-btn quizsnap-share-${p.icon}`}
        >
          {p.name}
        </button>
      ))}
      <button onClick={() => handleCopyLink(shareUrl)} aria-label="Copy link">
        Copy Link
      </button>
    </div>
  );
}

async function handleCopyLink(url: string) {
  await navigator.clipboard.writeText(url);
  trackShareEvent("copy_link");
}
