## Share Tracking Analytics

```tsx
// Storefront API endpoint: POST /apps/quizsnap/api/track-share
export async function action({ request }: ActionFunctionArgs) {
  const body = await request.json();
  const { sessionId, platform } = body;

  if (!sessionId || !platform) {
    return json({ error: "Missing fields" }, { status: 400 });
  }

  const validPlatforms = ["facebook", "twitter", "pinterest", "whatsapp", "copy_link", "email"];
  if (!validPlatforms.includes(platform)) {
    return json({ error: "Invalid platform" }, { status: 400 });
  }

  console.log(`[Share] Session ${sessionId} shared on ${platform}`);

  return json({ success: true });
}
